```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name pod, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search%' AND metric='k8s.container.restarts' ORDER BY time",
          "claim": "Search pod restart counter climbs from 4 to 8 during the incident; normal period was flat at 3."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),2) avg_v, round(max(value),2) max_v, count(*) n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search%' AND metric='k8s.container.ready' GROUP BY 1",
          "claim": "Search container readiness averages 0 across the whole abnormal window; it never recovers."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL",
          "claim": "All 565 /hotels server spans return 500, and every frontend call to search.Search/Nearby errors."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 1219 ERROR entries with message 'Search service failed'; search itself emits no logs."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY ALL",
          "claim": "Search call failures in frontend Client spans line up one-to-one with frontend /hotels HTTP 500 responses."
        }
      ]
    }
  ]
}
```

